    c = is_down(q) ? :white : :black,
    markerstrokecolor = is_down(q) ? :black : :white,
    shape = is_center(q) ? :circle : :diamond,
    ms = (is_center(q) ? 8 : 9) + (is_down(q) ? 0 : 1),
    markerstrokewidth = is_down(q) ? 2 : 4,
)
